const X = window.GYX;

/* 🌳 秘密树洞：把秘密说给 TA 听，TA 会认真回应、替你守着（你也能决定 TA 以后记不记得）；TA 也有自己的秘密，你们聊得越久，TA 就会慢慢告诉你一个 */
if (window.__gyxSecret) return; window.__gyxSecret = 1;
X.feat('gyxSecret', { n: '🌳 秘密树洞', desc: '说给 TA 的秘密；TA 的秘密会慢慢告诉你' });
